// Schema `auth`: the tables of the session library (Better Auth 1.7.19) and the
// product-owned second factor (Run 2.3, D-19).
//
// Rules that hold here as in `app`: ids are uuids generated by the application,
// every timestamp is `timestamptz`. No column holds a usable credential:
// - `session.token` holds a keyed verifier `v1.<keyId>.<base64url>`, never the token;
// - `account.password` holds a password hash;
// - the OAuth token columns of `account` exist because the library's schema
//   names them, and a check keeps them empty (no social provider is configured);
// - `totp_enrollment.seed_jwe` is ciphertext; `recovery_code.verifier` is an HMAC.
import { sql, type SQL } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  customType,
  foreignKey,
  index,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";
import { authSchema } from "./reserved.ts";

const bytea = customType<{ data: Buffer }>({ dataType: () => "bytea" });
const timestamptz = (name: string) => timestamp(name, { withTimezone: true });

/** `column IN ('a', 'b')`. The values are fixed lists in this file, never input. */
function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map((value) => `'${value}'`).join(", "))})`;
}

export const SESSION_PHASES = ["password_verified", "enrollment", "mfa_complete"] as const;
export const ACCOUNT_STATES = [
  "enrollment_pending",
  "active",
  "recovery_pending",
  "disabled",
] as const;
export const ENROLLMENT_STATES = ["pending", "active", "retired"] as const;

// ------------------------------------------------------------ Better Auth

export const user = authSchema.table("user", {
  id: uuid("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  createdAt: timestamptz("created_at").notNull().defaultNow(),
  updatedAt: timestamptz("updated_at").notNull().defaultNow(),
});

export const session = authSchema.table(
  "session",
  {
    id: uuid("id").primaryKey(),
    /** `v1.<keyId>.<base64url(HMAC-SHA-256(lookup key, raw token))>` (P-26). */
    token: text("token").notNull().unique(),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    expiresAt: timestamptz("expires_at").notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
    phase: text("phase").notNull().default("password_verified"),
    authEpoch: bigint("auth_epoch", { mode: "number" }).notNull().default(0),
    authenticatedAt: timestamptz("authenticated_at").notNull().defaultNow(),
    lastUserActivityAt: timestamptz("last_user_activity_at").notNull().defaultNow(),
    totpVerifiedAt: timestamptz("totp_verified_at"),
    enrollmentId: uuid("enrollment_id"),
    /** Run 3.6: set on the challenge session of an `mfa` reset, which may only enroll. */
    resetTokenId: uuid("reset_token_id").references((): AnyPgColumn => resetToken.id),
  },
  (t) => [
    check("session_phase_check", oneOf(t.phase, SESSION_PHASES)),
    // A stored token is a verifier, never a raw token.
    check(
      "session_token_verifier_check",
      sql`${t.token} ~ '^v1\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]{43}$'`,
    ),
    index("session_user_id_idx").on(t.userId),
  ],
);

export const account = authSchema.table(
  "account",
  {
    id: uuid("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamptz("access_token_expires_at"),
    refreshTokenExpiresAt: timestamptz("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (t) => [
    check(
      "account_no_provider_tokens_check",
      sql`${t.accessToken} is null and ${t.refreshToken} is null and ${t.idToken} is null`,
    ),
    check("account_provider_check", sql`${t.providerId} = 'credential'`),
    unique("account_provider_account_key").on(t.providerId, t.accountId),
    index("account_user_id_idx").on(t.userId),
  ],
);

export const verification = authSchema.table(
  "verification",
  {
    id: uuid("id").primaryKey(),
    /** Stored hashed (`verification.storeIdentifier: "hashed"`). */
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamptz("expires_at").notNull(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);

// ------------------------------------------------------- product tables

export const accountState = authSchema.table(
  "account_state",
  {
    userId: uuid("user_id")
      .primaryKey()
      .references(() => user.id, { onDelete: "cascade" }),
    state: text("state").notNull(),
    authEpoch: bigint("auth_epoch", { mode: "number" }).notNull().default(0),
    credentialEpoch: bigint("credential_epoch", { mode: "number" }).notNull().default(0),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
  },
  (t) => [check("account_state_state_check", oneOf(t.state, ACCOUNT_STATES))],
);

export const totpEnrollment = authSchema.table(
  "totp_enrollment",
  {
    id: uuid("id").primaryKey(),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** Compact JWE (`dir`, `A256GCM`) bound to the user and the enrollment. */
    seedJwe: text("seed_jwe").notNull(),
    keyId: text("key_id").notNull(),
    state: text("state").notNull(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    activatedAt: timestamptz("activated_at"),
  },
  (t) => [
    check("totp_enrollment_state_check", oneOf(t.state, ENROLLMENT_STATES)),
    uniqueIndex("totp_enrollment_one_active_idx")
      .on(t.userId)
      .where(sql`${t.state} = 'active'`),
  ],
);

export const totpStepUsed = authSchema.table(
  "totp_step_used",
  {
    enrollmentId: uuid("enrollment_id").notNull(),
    step: bigint("step", { mode: "number" }).notNull(),
    usedAt: timestamptz("used_at").notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: "totp_step_used_pkey", columns: [t.enrollmentId, t.step] }),
    foreignKey({
      name: "totp_step_used_enrollment_fk",
      columns: [t.enrollmentId],
      foreignColumns: [totpEnrollment.id],
    }).onDelete("cascade"),
  ],
);

export const recoveryCode = authSchema.table(
  "recovery_code",
  {
    id: uuid("id").primaryKey(),
    enrollmentId: uuid("enrollment_id").notNull(),
    /** HMAC-SHA-256(recovery key, enrollmentId || code). */
    verifier: bytea("verifier").notNull(),
    keyId: text("key_id").notNull(),
    consumedAt: timestamptz("consumed_at"),
    consumedBySession: uuid("consumed_by_session"),
  },
  (t) => [
    unique("recovery_code_enrollment_verifier_key").on(t.enrollmentId, t.verifier),
    foreignKey({
      name: "recovery_code_enrollment_fk",
      columns: [t.enrollmentId],
      foreignColumns: [totpEnrollment.id],
    }).onDelete("cascade"),
  ],
);

/**
 * Run 3.6 (P-51, D-30): an operator-issued reset. The token itself is never
 * stored: `verifier` is HMAC-SHA-256(reset key, token) under `key_id`, and is
 * set to NULL when the token is consumed, superseded or expired.
 */
export const resetToken = authSchema.table(
  "reset_token",
  {
    id: uuid("id").primaryKey(),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    verifier: bytea("verifier").unique("reset_token_verifier_key"),
    keyId: text("key_id").notNull(),
    kind: text("kind").notNull(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    expiresAt: timestamptz("expires_at").notNull(),
    consumedAt: timestamptz("consumed_at"),
    supersededAt: timestamptz("superseded_at"),
  },
  (t) => [
    check("reset_token_kind_check", oneOf(t.kind, ["password", "mfa"])),
    index("reset_token_user_id_idx").on(t.userId),
  ],
);
